  return `<!doctype html><html lang="ru" data-site-base="${e(siteBase)}" data-vote-api="${e(voteApiUrl)}"${ymCounterId ? ` data-ym-counter="${e(ymCounterId)}"` : ''}><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f3e9"><meta name="mitgo-verification" content="c50c6d4d-072c-4a42-b285-e126302d0b9d"><meta name="yandex-verification" content="144a182fc221dbf0"><meta name="google-site-verification" content="gcFQXlUlDUrWNKEJ4RkrCtgBjwGZKrObcyiFYU9phS8"><title>${e(title)} · МАЛИНА — КЛУБНИКА</title><meta name="description" content="${e(description)}">${canonical}${robots ? `<meta name="robots" content="${e(robots)}">` : ''}${socialMeta}<link rel="icon" type="image/svg+xml" href="/assets/favicon.svg">${siteUrl ? '<link rel="alternate" type="application/rss+xml" title="Ягодный журнал МАЛИНА — КЛУБНИКА" href="/feed.xml">' : ''}<link rel="stylesheet" href="/assets/site.css"><script defer src="/assets/site.js"></script><script id="vote-snapshot" type="application/json">${JSON.stringify(voteSnapshot)}</script><script type="module" src="/assets/votes.js"></script>${structuredScript}${script}</head><body><a class="skip-link" href="#main">К содержимому</a>${header(active)}${cookieNotice()}<main id="main">${body}</main>${footer()}</body></html>`;
