function varietyCard(v, index = 0, picker = false) { const image = cultivarImage(v); const n = String(index + 1).padStart(2, '0'); return `<article class="variety-card" data-crop="${v.cropKey}" data-setting="${v.setting}" data-season="${v.season}" data-harvest-timing="${e(v.harvestTiming)}" data-fruiting="${v.fruiting}" data-fruit-color="${e(v.fruitColor ?? 'unknown')}" data-name="${e(`${v.name} ${v.latin}`.toLocaleLowerCase('ru'))}"${picker === true ? ` data-cultivar-slug="${e(v.slug)}" data-light="${e(v.light)}" data-place-label="${e(v.place)}" data-period-label="${e(v.period)}" data-fruiting-label="${e(v.fruitingLabel)}" data-reviewed-at="${e(v.reviewedAt ?? reviewedAt)}"` : ''}><div class="variety-card-top">${picker ? '' : `<span class="variety-number">${n} / ${String(varieties.length).padStart(2, '0')}</span>`}<span class="mini-tag">${v.crop}</span></div><figure class="variety-card-media"><a href="/sorta/${v.slug}/"><img src="${image.src}" alt="${e(image.alt)}" width="${image.width}" height="${image.height}" loading="lazy" decoding="async"></a><figcaption>${image.caption}</figcaption></figure><div class="variety-card-body"><span class="small-label">${e(v.fruitingLabel)}</span><h3><a href="/sorta/${v.slug}/">${e(v.name)}</a></h3><p>${e(v.note)}</p>${picker === true ? `<div class="picker-match" hidden><strong>Подходит по выбранным условиям</strong><p class="picker-match-why"></p></div><div class="picker-admission" hidden></div><label class="picker-compare-option" hidden><input type="checkbox" class="picker-compare-checkbox" value="${e(v.slug)}"><span>Сравнить «${e(v.name)}»</span></label><button class="picker-memo-open" type="button">Памятка по сорту ↓</button>` : ''}${voteWidget(v, voteSnapshot, voteApiUrl)}<dl class="catalog-facts"><div><dt>Плодоношение</dt><dd>${e(v.type)}</dd></div><div><dt>Срок</dt><dd>${e(v.period)}</dd></div><div><dt>Место</dt><dd>${e(v.place)}</dd></div></dl><a class="catalog-source" href="${e(v.source)}" target="_blank" rel="noopener noreferrer">Источник: ${e(v.sourceLabel)} ↗</a><div class="variety-card-bottom"><span>${e(v.place)}</span><a aria-label="Подробнее о сорте ${e(v.name)}" href="/sorta/${v.slug}/">${arrow}</a></div></div></article>`; }
const articlePath = article => `/zhurnal/${article.slug}/`;
