function comparePage(cropKey) {
  const isRaspberry = cropKey === 'raspberry';
  const cropName = isRaspberry ? 'малины' : 'клубники';
  const route = `/sravnenie/${isRaspberry ? 'malina' : 'klubnika'}/`;
  const cropVarieties = varieties.filter(item => item.cropKey === cropKey);
  const initialVarieties = cropVarieties.slice(0, 4);
  const comparisonData = JSON.stringify({
    varieties: cropVarieties.map(item => {
      const publicRecord = publicCultivars.get(item.slug);
      const yieldObservation = publicRecord?.observations?.find(row =>
        row.trait_code === 'yield' && row.evidence &&
        ((Number.isFinite(row.value_number) && row.unit) || String(row.value_text || '').trim())
      ) || null;
      const yieldObservations = (publicRecord?.observations || []).filter(row => row.trait_code === 'yield' && row.evidence);
      return { ...item, admissions: publicRecord?.admissions || [], yieldObservation, yieldObservations };
    }),
    cities,
    regions: publicCatalog.regions
  }).replaceAll('<', '\\u003c');
  const choices = cropVarieties.map(item => `<label class="comparison-choice"><input type="checkbox" name="cultivar" value="${e(item.slug)}"${initialVarieties.includes(item) ? ' checked' : ''}><span><strong>${e(item.name)}</strong></span><a href="/sorta/${e(item.slug)}/">Карточка сорта ↗</a></label>`).join('');
  const facts = initialVarieties.map(item => `<th scope="col"><a href="/sorta/${e(item.slug)}/">${e(item.name)}</a></th>`).join('');
  const factDefinitions = [
    ['Культура', item => item.crop],
    ['Тип плодоношения', item => item.fruitingLabel],
    ['Период по источнику', item => item.period],
    ['Указанное место выращивания', item => item.place],
    ['Что сообщает источник', item => item.note]
  ];
  const rows = [
    ...factDefinitions.map(([label, getValue]) => `<tr><th scope="row">${e(label)}</th>${initialVarieties.map(item => `<td>${e(getValue(item) || '—')}<a class="comparison-source" href="${e(item.source)}" target="_blank" rel="noopener noreferrer">${e(item.sourceLabel)} · проверено ${e(item.reviewedAt ?? reviewedAt)} ↗</a></td>`).join('')}</tr>`),
    `<tr><th scope="row">Урожайность в источнике</th>${initialVarieties.map(item => {
      const publicRecord = publicCultivars.get(item.slug);
      const studies = getComparisonYields({ observations: publicRecord?.observations || [] });
      if (!studies.length) return '<td>—</td>';
      return `<td>${studies.map(yieldData => {
        const context = yieldData.context ? `<small>${e(yieldData.context)}</small>` : '';
        const source = yieldData.sourceUrl ? `<a class="comparison-source" href="${e(yieldData.sourceUrl)}" target="_blank" rel="noopener noreferrer">${e(yieldData.sourceTitle)}${yieldData.sourceLocator ? ` · ${e(yieldData.sourceLocator)}` : ''} ↗</a>` : '';
        return `<div class="comparison-yield"><strong>${e(yieldData.value)}</strong>${context}${source}</div>`;
      }).join('')}</td>`;
    }).join('')}</tr>`
  ].join('');
  return layout({ title: `Сравнить сорта ${cropName}`, description: `Сравните характеристики сортов ${cropName} и откройте исходные описания.`, path: route, active: 'catalog', script: '<script type="module" src="/assets/comparison.js"></script>', body: `<section class="simple-hero comparison-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span><a href="/sorta/">Каталог сортов</a><span> / </span>Сравнение</div><span class="eyebrow">АТЛАС / СРАВНЕНИЕ ПО ИСТОЧНИКАМ</span><h1>Сравнить сорта<br><em>${isRaspberry ? 'малины.' : 'клубники.'}</em></h1><p>Сравните характеристики сортов и откройте источник в любой строке.</p></div></section><section class="section wrap comparison-section" id="comparison" data-crop="${cropKey}" data-reviewed-at="${e(reviewedAt)}"><script id="comparison-data" type="application/json">${comparisonData}</script><div class="comparison-intro"><div><span class="eyebrow">ВАШЕ СРАВНЕНИЕ</span><p id="comparison-context" class="comparison-context" hidden></p></div><a class="text-link" href="/sorta/">Вернуться в каталог ↗</a></div><p class="comparison-status" id="comparison-status" role="status" aria-live="polite">Выберите сорта для сравнения.</p><div class="comparison-table-wrap" tabindex="0" role="region" aria-label="Таблица сравнения сортов. На узком экране её можно прокручивать по горизонтали."><table class="comparison-table"><caption>Характеристики сортов ${cropName} по исходным описаниям.</caption><thead><tr><th scope="col">Параметр</th>${facts}</tr></thead><tbody id="comparison-rows">${rows}</tbody></table></div><details class="comparison-chooser" id="comparison-chooser"><summary>Изменить сорта для сравнения</summary><p>Выберите от двух до четырёх сортов. В каталоге ${cropVarieties.length} вариантов.</p><fieldset class="comparison-choices"><legend>Сорта для сравнения</legend>${choices}</fieldset></details><p class="comparison-limits">Для выбора под свой город откройте подбор и сравните региональные данные.</p></section>` });
}

const pickerPlaceOptions = [
  ...cities.map(city => ({ name: city.name, region: city.region, city: city.name })),
  ...[...new Set(cities.map(city => city.region))].sort((a, b) => a.localeCompare(b, 'ru'))
    .map(region => ({ name: region, region, city: '' }))
].map(place => `<option value="${e(place.name)}" data-region="${e(place.region)}" data-city="${e(place.city)}" label="${e(place.city ? place.region : 'Регион России')}"></option>`).join('');

const picker = layout({ title: 'Подобрать сорт по условиям участка', description: 'Выбор региона России и условий участка для справочного сравнения сортов малины и клубники.', path: '/podbor/', body: `<section class="simple-hero picker-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span>Подбор сорта</div><span class="eyebrow">НАЧНИТЕ С УСЛОВИЙ УЧАСТКА</span><h1>Свой сад.<br><em>Свой сорт.</em></h1><p>Укажите город или регион и выберите малину или клубнику.</p></div></section><section class="section wrap picker-layout"><form class="picker-form" id="picker-form"><div class="picker-step"><span class="step-index">Место</span><label class="region-label" for="picker-region">В каком регионе ваш участок?</label><input class="region-input" id="picker-region" name="region" type="text" list="picker-places" placeholder="Город или регион, например Тула" autocomplete="off" maxlength="80" aria-describedby="picker-place-help picker-place-error" required><datalist id="picker-places">${pickerPlaceOptions}</datalist><p class="field-help" id="picker-place-help">Начните вводить город или регион и выберите вариант из списка.</p><p class="field-help picker-place-error" id="picker-place-error" role="alert" hidden>Не нашли место в списке. Проверьте написание или продолжите общее сравнение.</p><button class="picker-place-continue" id="picker-place-continue" type="button" hidden>Продолжить без региональных данных →</button><p class="field-help picker-city-context" id="picker-city-context" hidden></p></div><div class="picker-step"><span class="step-index">Культура</span><fieldset><legend>Что хотите выращивать?</legend><div class="choice-row"><label><input type="radio" name="crop" value="all" checked><span>Пока выбираю</span></label><label><input type="radio" name="crop" value="raspberry"><span>Малину</span></label><label><input type="radio" name="crop" value="strawberry"><span>Клубнику</span></label></div></fieldset></div><details class="picker-advanced"><summary>Уточнить условия участка <span>необязательно</span></summary><div class="picker-advanced-fields"><div class="picker-step"><fieldset><legend>Где будет расти?</legend><div class="choice-row"><label><input type="radio" name="setting" value="all" checked><span>Пока не решил(а)</span></label><label><input type="radio" name="setting" value="ground"><span>На грядке</span></label><label><input type="radio" name="setting" value="container"><span>В контейнере</span></label></div></fieldset></div><div class="picker-step"><fieldset><legend>Сколько света на месте?</legend><div class="choice-row"><label><input type="radio" name="light" value="sun"><span>Солнечно</span></label><label><input type="radio" name="light" value="shade"><span>Есть заметная тень</span></label><label><input type="radio" name="light" value="unknown" checked><span>Пока не знаю</span></label></div></fieldset></div><div class="picker-step"><fieldset><legend>Какой тип плодоношения?</legend><div class="choice-row"><label><input type="radio" name="fruiting" value="all" checked><span>Любой</span></label><label><input type="radio" name="fruiting" value="remontant"><span>Ремонтантный</span></label><label><input type="radio" name="fruiting" value="summer"><span>Летний</span></label></div><p class="field-help">Для малины это плодоношение на побегах текущего года, для клубники — повторное плодоношение в течение сезона. Сроки зависят от региона и условий.</p></fieldset></div><div class="picker-step"><fieldset><legend>Какой срок сбора интересует?</legend><div class="choice-row"><label><input type="radio" name="harvestTiming" value="all" checked><span>Любой</span></label><label><input type="radio" name="harvestTiming" value="early"><span>Ранний или среднеранний</span></label><label><input type="radio" name="harvestTiming" value="middle"><span>Средний</span></label><label><input type="radio" name="harvestTiming" value="late"><span>Поздний</span></label><label><input type="radio" name="harvestTiming" value="autumn"><span>Осенний</span></label><label><input type="radio" name="harvestTiming" value="repeat"><span>Повторный сбор</span></label></div><p class="field-help">Сравните ранний, средний и поздний сроки из описаний сортов.</p></fieldset></div><div class="picker-step"><fieldset><legend>Планируете укрывать растения на зиму?</legend><div class="choice-row"><label><input type="radio" name="shelter" value="unknown" checked><span>Пока не знаю</span></label><label><input type="radio" name="shelter" value="yes"><span>Да</span></label><label><input type="radio" name="shelter" value="no"><span>Нет</span></label></div><p class="field-help">Отметьте условия участка для памятки после подбора.</p></fieldset></div><div class="picker-step"><fieldset><legend>Что происходит с водой после дождя?</legend><div class="choice-row"><label><input type="radio" name="drainage" value="unknown" checked><span>Пока не знаю</span></label><label><input type="radio" name="drainage" value="wet"><span>Долго стоит</span></label><label><input type="radio" name="drainage" value="drained"><span>Быстро уходит</span></label></div><p class="field-help">Отметьте то, что уже наблюдали на участке.</p></fieldset></div></div></details><button class="btn btn-dark picker-submit" type="submit">Показать сорта ${arrow}</button></form><aside class="picker-aside"><div class="picker-marks" aria-hidden="true">${cropMark('raspberry')}${cropMark('strawberry')}</div><h2>Как мы подбираем</h2><p>Покажем сорта. Подробности и источники — в карточке каждого.</p><a href="/about/">О наших источниках ↗</a></aside></section><section class="section wrap results-section" id="picker-output" hidden tabindex="-1" aria-live="polite"><span class="eyebrow">ВАШ РЕЗУЛЬТАТ</span><h2 id="picker-title">Сорта для сравнения</h2><p id="picker-region-status" class="region-status"></p><p id="picker-conditions" class="region-status" hidden></p><div class="picker-result-controls"><button id="picker-edit-conditions" class="picker-edit-conditions" type="button">← Изменить условия</button></div><div class="picker-compare-bar" id="picker-compare-bar" hidden><p id="picker-compare-status" role="status" aria-live="polite">Отметьте 2–4 сорта для сравнения.</p><a id="picker-compare-link" class="btn btn-dark" href="/sravnenie/malina/" hidden>Сравнить выбранные ↗</a></div><div class="variety-grid" id="picker-results">${varieties.map((v, i) => varietyCard(v, i, true)).join('')}</div><button class="picker-show-more" id="picker-show-more" type="button" hidden>Показать ещё сорта</button><article class="picker-memo" id="picker-memo" hidden tabindex="-1" aria-labelledby="picker-memo-title"><div class="picker-memo-top"><span class="eyebrow">СОХРАНИТЕ ДЛЯ САДА</span><button type="button" class="picker-memo-close" id="picker-memo-close" aria-label="Закрыть памятку">Закрыть ×</button></div><h3 id="picker-memo-title"></h3><p class="picker-memo-lead" id="picker-memo-lead"></p><dl id="picker-memo-facts"></dl><h4>Что проверить дальше</h4><ol id="picker-memo-steps"></ol><p class="picker-memo-limit">Памятка соберёт выбранные условия, сорта и вопросы для проверки перед посадкой.</p><div class="picker-memo-sources" id="picker-memo-sources"></div><p class="picker-memo-date" id="picker-memo-date"></p><div class="picker-memo-actions"><button type="button" class="btn btn-dark" id="picker-memo-print">Распечатать / сохранить PDF ↓</button><span>В окне печати выберите «Сохранить как PDF». Файл будет открываться без интернета.</span></div></article><div class="empty-state" id="picker-empty" hidden><h3>Вариантов по этим условиям нет</h3><p>Для этих условий совпадений в подборке нет. Измените один параметр или откройте весь каталог.</p><a class="text-link" href="/sorta/">Открыть каталог ↗</a></div>${note}</section>`, script: '<script type="module" src="/assets/picker-wizard.js"></script><script type="module" src="/assets/picker-compare.js"></script><script type="module" src="/assets/picker-memo.js"></script>' });

