function cityPickerPage(city) {
  const path = `/podbor/${city.slug}/`;
  const title = `Подбор сортов малины и клубники — ${city.name}`;
  const description = `Подбор малины и клубники для сада в городе ${city.name} (${city.region}): сравните сорта, условия участка и записи Госреестра.`;
  const citySearch = e(new URLSearchParams({ city: city.name, region: city.region }).toString());
  const region = publicCatalog.regions.find(item => item.name_ru === city.region);
  const admissions = region?.admission_region_number
    ? publicCatalog.cultivars.flatMap(cultivar => (cultivar.admissions || [])
      .filter(admission => admission.admission_region_number === region.admission_region_number)
      .map(admission => ({ cultivar, admission })))
    : [];
  const admissionList = admissions.map(({ cultivar, admission }) => {
    const source = admission.source_pdf_page
      ? `${admission.source_url}#page=${admission.source_pdf_page}`
      : admission.source_url;
    return `<li class="admission-result"><h3>${e(cultivar.canonical_name)} · допуск в Госреестре</h3><p>${e(region.admission_region_name)} регион (${region.admission_region_number}); издание на ${e(admission.edition_as_of)}, запись ${e(admission.registry_entry_code)}. Откройте карточку, чтобы посмотреть источник и характеристики.</p><a href="/sorta/${e(cultivar.slug)}/?${citySearch}#gosreestr">Карточка сорта ↗</a><a href="/sorta/${e(cultivar.slug)}/?${citySearch}#otzyvy">Отзывы садоводов ↗</a><a href="${e(source)}" target="_blank" rel="noopener noreferrer">Строка реестра ↗</a></li>`;
  }).join('');
  const initialStatus = admissions.length
    ? `Записи Госреестра 2024 года для региона «${city.region}». Откройте сорт для подробностей.`
    : `Регион: ${city.region}. Уточните условия участка, чтобы сравнить сорта.`;
  let html = pickerPage
    .replace('<title>Подобрать сорт по условиям участка · МАЛИНА — КЛУБНИКА</title>', `<title>${e(title)} · МАЛИНА — КЛУБНИКА</title>`)
    .replaceAll('Выбор региона России и условий участка для справочного сравнения сортов малины и клубники.', e(description))
    .replace('<h1>Свой сад.<br><em>Свой сорт.</em></h1>', `<h1>Ягодный сад:<br><em>${e(city.name)}.</em></h1>`)
    .replace('Укажите город или регион и выберите малину или клубнику.', 'Выберите малину или клубнику. Условия участка можно уточнить по желанию.')
    .replace('id="picker-form"', `id="picker-form" data-city="${e(city.name)}" data-region="${e(city.region)}"`)
    .replace('id="picker-region" name="region"', `id="picker-region" name="region" value="${e(city.region)}"`)
    .replace('<p id="verified-status">Укажите регион и нажмите «Показать сорта» выше.</p><ul id="verified-results"></ul>',
      `<p id="verified-status">${e(initialStatus)}</p><ul id="verified-results">${admissionList}</ul>`)
    .replace(/href="(\/sorta\/[a-z0-9-]+\/)(#[^"]*)?"/g, (_, cultivarPath, fragment = '') =>
      `href="${cultivarPath}?${citySearch}${fragment}"`)
    .replace('</head>', '<meta name="robots" content="noindex,follow"></head>');
  if (siteUrl) {
    html = html.replace(`href="${siteUrl}/podbor/"`, `href="${siteUrl}${path}"`)
      .replace(`content="${siteUrl}/podbor/"`, `content="${siteUrl}${path}"`);
  }
  return html;
}

function yieldEvidence(v) {
  const findings = getComparisonYields({ observations: publicCultivars.get(v.slug)?.observations || [] });
  if (!findings.length) return {
    fact: '—',
    details: '',
    hasEvidence: false
  };
  if (findings.length === 1) return {
    fact: `${findings[0].value} · ${findings[0].context}`,
    details: '',
    hasEvidence: true
  };
  const count = findings.length;
  const noun = count % 100 >= 11 && count % 100 <= 14 ? 'измерений'
    : count % 10 === 1 ? 'измерение' : count % 10 >= 2 && count % 10 <= 4 ? 'измерения' : 'измерений';
  return {
    fact: `${count} ${noun}`,
    details: `<div class="facts-yield-list"><span>Результаты исследований</span><ul>${findings.map(finding => `<li><strong>${e(finding.value)}</strong><small>${e(finding.context)}</small><a href="${e(finding.sourceUrl)}" target="_blank" rel="noopener noreferrer" aria-label="Открыть исследование: ${e(finding.sourceTitle)}, ${e(finding.sourceLocator)}">Открыть исследование ↗</a></li>`).join('')}</ul></div>`,
    hasEvidence: true
  };
}

function renderVarietySources(v) {
  const sources = [
    { url: v.source, label: v.sourceLabel },
    ...(v.secondarySource ? [{ url: v.secondarySource, label: v.secondarySourceLabel }] : []),
    ...(v.additionalSources ?? [])
  ].filter((source, index, all) => source.url && all.findIndex((item) => item.url === source.url) === index);
  return sources.map((source) => `<a class="btn btn-outline" href="${e(source.url)}" target="_blank" rel="noopener noreferrer">${e(source.label)} ↗</a>`).join('');
}

function varietyPage(v) { const image = cultivarImage(v); const cropTitle = v.cropKey === 'raspberry' ? 'Малина' : 'Клубника'; const yieldData = yieldEvidence(v); const metaDescription = yieldData.hasEvidence ? `${cropTitle} «${v.name}»: описание сорта, фото, урожайность по источникам и отзывы садоводов.` : `${cropTitle} «${v.name}»: описание сорта, фото и отзывы садоводов. Характеристики и первоисточник — в карточке.`; return layout({ socialImage: image.src, socialImageAlt: image.alt, socialImageWidth: image.width, socialImageHeight: image.height, title: `${cropTitle} ${v.name}: описание сорта, фото, урожайность, отзывы садоводов`, description: metaDescription, path: `/sorta/${v.slug}/`, active: 'catalog', body: `<section class="variety-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span><a href="/sorta/">Каталог</a><span> / </span>${e(v.name)}</div><div class="variety-hero-grid"><div><span class="eyebrow">${e(v.crop)} / СОРТ И ОПЫТ САДОВОДОВ</span><h1>${e(v.name)}<span class="period">.</span></h1><p class="lead">${e(v.note)}</p>${voteWidget(v, voteSnapshot, voteApiUrl)}${voteFreshness(voteSnapshot)}<a class="btn btn-dark" id="variety-picker-link" href="/podbor/">Сравнить с условиями ${arrow}</a></div><figure class="variety-hero-art cultivar-illustration ${v.cropKey}"><img src="${image.src}" alt="${e(image.alt)}" width="${image.width}" height="${image.height}" fetchpriority="high"><figcaption>${image.caption}</figcaption></figure></div></div></section><section class="section wrap facts-section"><div class="facts-intro"><span class="eyebrow">КРАТКО О СОРТЕ</span><h2>Что известно<br>из источника</h2><p>Сравните характеристики сорта и условия, при которых измеряли урожайность.</p></div><div class="facts-grid"><div><span>Культура</span><strong>${e(v.crop)}</strong></div><div><span>Группа</span><strong>${e(v.fruitingLabel)}</strong></div>${v.cropKey === 'raspberry' ? `<div><span>Цвет ягоды</span><strong>${e(v.fruitColor === 'red' ? 'Красная' : v.fruitColor === 'yellow' ? 'Жёлтая / золотистая' : '—')}</strong></div>` : ''}<div><span>Тип</span><strong>${e(v.type)}</strong></div><div><span>Период</span><strong>${e(v.period)}</strong></div><div><span>Для сравнения</span><strong>${e(v.place)}</strong></div><div><span>Урожайность</span><strong>${e(yieldData.fact)}</strong></div>${yieldData.details}</div></section><section class="section wrap source-panel"><div><span class="eyebrow">ПРОИСХОЖДЕНИЕ ДАННЫХ</span><h2>Проверяйте первоисточник.</h2><p>Откройте исходное описание и проверьте условия испытания сорта.</p></div><div class="source-actions"><span>Описание сверено с источником: ${v.reviewedAt ?? reviewedAt}</span>${renderVarietySources(v)}</div></section><section class="section wrap"><div class="next-row"><h2>Следующий шаг</h2><p>Сравните сорт с условиями участка и прочитайте опыт садоводов.</p><div class="variety-next-actions"><a class="btn btn-dark" href="#otzyvy">Опыт садоводов и отзывы ${arrow}</a><a class="text-link" href="/instrumenty/zhurnal-uchastka/?crop=${e(v.cropKey)}&amp;cultivar=${encodeURIComponent(v.name)}">Записать свой сезон ↗</a></div></div></section>` }); }

const guide = layout({ title: 'Как выбрать сорт для ягодного сада', description: 'Три вопроса перед выбором сорта малины или клубники: культура, место и источник данных.', path: '/guide/', active: 'guide', body: `<section class="simple-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span>Как выбрать</div><span class="eyebrow">КРАТКОЕ РУКОВОДСТВО</span><h1>Выбирайте<br><em>осознанно.</em></h1><p>Название сорта — начало разговора. Условия участка и качество источника помогают понять, стоит ли рассматривать его дальше.</p></div></section><section class="section wrap article-layout"><aside class="article-index"><span class="eyebrow">НА ЭТОЙ СТРАНИЦЕ</span><a href="#place">01 — Место</a><a href="#season">02 — Сезон</a><a href="#source">03 — Источник</a><a href="#next">04 — Что дальше</a></aside><article class="guide-article"><section id="place"><span>01 / МЕСТО</span><h2>Начните с участка</h2><p>Отметьте освещённость, способ выращивания и особенности почвы. Сверьте освещённость участка с описанием выбранного сорта.</p></section><section id="season"><span>02 / СЕЗОН</span><h2>Выберите ритм сбора</h2><p>Ремонтантная малина даёт основной урожай на побегах текущего года; для двух сборов нужна особая схема обрезки. Ремонтантной клубникой обычно называют сорта с повторным плодоношением в течение сезона. Сравните сроки созревания с вашим сезоном.</p></section><section id="source"><span>03 / ИСТОЧНИК</span><h2>Проверьте обещания</h2><p>Ищите исходное описание сорта и выясняйте, для какого региона получены наблюдения. Слова «урожайный» или «зимостойкий» без условий опыта мало помогают принять решение.</p><p>Для сравнения ухода используйте <a href="https://rosselhoscenter.ru/ob-uchrezhdenii/filialy/tsentralnyy-okrug/tulskaya-oblast/obrezka-maliny-osenyu/" target="_blank" rel="noopener noreferrer">Россельхозцентр · малина ↗</a> и <a href="https://rosselhoscenter.ru/ob-uchrezhdenii/filialy/sibirskiy/omskaya-oblast/osennyaya-posadka-sadovoy-zemlyaniki/" target="_blank" rel="noopener noreferrer">Россельхозцентр · клубника ↗</a>. Для регионального выбора перейдите в подбор.</p></section><section id="next"><span>04 / СЛЕДУЮЩИЙ ШАГ</span><h2>Сравните варианты</h2><p>Используйте подбор как фильтр для чтения карточек. Перед покупкой проверьте подлинность сорта, состояние растений, условия доставки и продавца. </p><a class="btn btn-dark" href="/podbor/">Начать подбор ${arrow}</a></section></article></section>` });

const inVitro = layout({ title: 'In Vitro и Ex Vitro: что важно знать о ягодных саженцах', description: 'Как получают микрорастения клубники, что значит адаптация Ex Vitro и какие документы проверять перед покупкой партии.', path: '/in-vitro/', body: `<section class="simple-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span>In Vitro</div><span class="eyebrow">ПОСАДОЧНЫЙ МАТЕРИАЛ / РАЗБИРАЕМСЯ</span><h1>Из лаборатории<br><em>в сад.</em></h1><p>In Vitro описывает способ размножения растений. Для выбора саженцев важны ещё происхождение сорта, адаптация и документы на конкретную партию.</p></div></section><section class="section wrap article-layout"><aside class="article-index"><span class="eyebrow">НА ЭТОЙ СТРАНИЦЕ</span><a href="#method">01 — Метод</a><a href="#stages">02 — Этапы</a><a href="#proof">03 — Что проверить</a><a href="#source">04 — Источник</a></aside><article class="guide-article"><section id="method"><span>01 / МЕТОД</span><h2>Что означает In Vitro</h2><p>При культуре тканей небольшую часть растения — эксплант — помещают в контролируемые стерильные условия. Один из подходов использует меристему, ткань точки роста. Затем растения размножают в культуре. Это способ производства посадочного материала, а не название сорта или знак качества партии.</p></section><section id="stages"><span>02 / ЭТАПЫ</span><h2>От микрорастения к саженцу</h2><p>После размножения микрорастения укореняют и переносят из сосуда в субстрат. Переход к условиям вне культуры называют адаптацией Ex Vitro. Поэтому «In Vitro», «Ex Vitro» и готовый укоренённый саженец — разные стадии; перед покупкой уточняйте, что именно отправят.</p></section><section id="proof"><span>03 / ДОКУМЕНТЫ</span><h2>Проверяйте конкретную партию</h2><p>Спросите о маточном растении и сортовой идентичности, дате адаптации, количестве и состоянии корней. Если продавец заявляет, что материал оздоровлен, запросите результат фитосанитарного тестирования: какие патогены проверяли, каким методом, когда и у какой партии. Проверяйте такие заявления по документам на конкретную партию.</p><p>Перед покупкой запросите документы на конкретную партию.</p></section><section id="source"><span>04 / ИСТОЧНИК</span><h2>На чём основано объяснение</h2><p><a href="https://www.scielo.cl/pdf/bres/v50/0716-9760-bres-s40659-017-0125-8.pdf" target="_blank" rel="noopener noreferrer">Исследование Quiroz и соавторов, 2017 ↗</a> описывает меристемную культуру, размножение, адаптацию и вирусное тестирование чилийской земляники. Работа показывает этапы производства и проверки материала.</p><a class="btn btn-dark" href="/guide/">Как выбирать сорт ${arrow}</a></section></article></section>` });

const cultivarLinkMap = e(JSON.stringify(Object.fromEntries(varieties.map(({ name, slug }) => [name, slug]))));

function cultivarReviews(v) {
  return `<section class="section wrap cultivar-reviews" id="otzyvy"><div class="reviews-layout" id="reviews-root" data-review-api="${e(reviewApiUrl)}" data-reviews-enabled="${reviewsEnabled}" data-cultivar="${e(v.name)}" data-cultivar-links="${cultivarLinkMap}"><div class="reviews-main"><span class="eyebrow">ОПЫТ ПО ЭТОМУ СОРТУ</span><h2>Отзывы о сорте ${e(v.name)}</h2><p id="reviews-filter" class="reviews-filter" hidden></p><div id="reviews-list" class="reviews-list" aria-live="polite"><p>Загружаем отзывы…</p></div><a class="text-link" id="reviews-next-link" href="/podbor/">Сравнить другие сорта ↗</a></div><aside class="reviews-compose"><span class="eyebrow">ВАШ ОПЫТ</span><h2>Написать отзыв</h2><p class="reviews-note">Укажите имя или псевдоним, регион и конкретный опыт выращивания этого сорта. Контактные данные не нужны.</p><form id="review-form"><fieldset ${reviewsEnabled ? '' : 'disabled'}><label for="review-name">Имя или псевдоним</label><input id="review-name" name="display_name" autocomplete="nickname" maxlength="80" required><label for="review-region">Город или регион</label><input id="review-region" name="region" autocomplete="off" maxlength="100" placeholder="Например, Калининградская область" required><input type="hidden" name="cultivar_name" value="${e(v.name)}"><label for="review-body">Ваш отзыв</label><textarea id="review-body" name="body" minlength="20" maxlength="2000" rows="6" placeholder="Что выращивали, в каких условиях и что заметили?" required></textarea><button class="btn btn-dark" type="submit" ${reviewsEnabled ? '' : 'disabled'}>Опубликовать отзыв ${arrow}</button><p class="reviews-smallprint">Сообщение будет проверено на спам и полезность. Телефон и электронная почта не запрашиваются.</p></fieldset></form><p id="review-status" class="review-status" role="status" aria-live="polite"></p></aside></div></section>`;
}

