const isCurrent = value => value && Number.isFinite(Date.parse(String(value).replace(' ', 'T') + 'Z')) && Date.parse(String(value).replace(' ', 'T') + 'Z') > Date.now();
const safeMerchantUrl = value => {
  try { const url = new URL(value); return url.protocol === 'https:' && !url.username && !url.password ? url.href : null; }
  catch { return null; }
};
function withCommerce(html, variety) {
  const row = publicCultivars.get(variety.slug);
  if (!row) return html;
  const offers = (row.offers || []).filter(offer => offer.kind === 'affiliate' && offer.checked_at && isCurrent(offer.expires_at) && safeMerchantUrl(offer.destination_url));
  const batches = (row.own_batches || []).filter(batch => batch.plant_stage === 'sale_ready' && batch.quantity_available > 0 && batch.checked_at && isCurrent(batch.expires_at));
  if (!offers.length && !batches.length) return html;
  const offerCards = offers.map(offer => `<article class="commerce-card"><span class="eyebrow">ПАРТНЁРСКОЕ ПРЕДЛОЖЕНИЕ</span><h3>${e(offer.product_name)}</h3><p>Продавец: ${e(offer.seller_name)}. Проверено: ${e(offer.checked_at.slice(0, 10))}.</p>${offer.price_minor != null && offer.currency === 'RUB' ? `<p>Цена при проверке: ${e(new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB' }).format(offer.price_minor / 100))}</p>` : ''}<a class="btn btn-dark" href="${e(safeMerchantUrl(offer.destination_url))}" target="_blank" rel="sponsored noopener noreferrer" data-affiliate-offer="${e(offer.id)}" data-cultivar="${e(variety.slug)}">Перейти к продавцу ${arrow}</a><small>Партнёрская ссылка. Цена и наличие могут измениться на сайте продавца.</small></article>`).join('');
  const batchCards = batches.map(batch => `<article class="commerce-card"><span class="eyebrow">СОБСТВЕННАЯ ПАРТИЯ</span><h3>Партия ${e(batch.batch_code)}</h3><p>${e(batch.provenance_summary)}</p><p>Готовых растений: ${e(batch.quantity_available)}. Получение: ${e(batch.pickup_locality)}, ${e(batch.pickup_region_name)}.</p><p>${e(batch.pickup_terms)}</p><small>Проверено: ${e(batch.checked_at.slice(0, 10))}.</small></article>`).join('');
  const section = `<section class="section wrap commerce-section"><span class="eyebrow">РЕАЛЬНЫЕ ПРЕДЛОЖЕНИЯ</span><h2>Где получить саженец</h2><div class="commerce-grid">${offerCards}${batchCards}</div></section>`;
  return html.replace('</main>', `${section}</main>`).replace('Проверенных предложений на сайте пока нет.', 'Проверенные предложения показаны ниже.');
}

const shopProductPath = product => `/magazin/${product.slug}/`;
const shopPrice = offer => new Intl.NumberFormat('ru-RU', { style: 'currency', currency: 'RUB', maximumFractionDigits: 2 }).format(offer.priceMinor / 100);
const shopCropLabel = product => product.crop === 'raspberry' ? 'Малина' : 'Клубника';
const shopIsSet = product => /Наборы земляники/u.test(product.categoryId || product.category || '');
const shopPlantLabel = product => shopIsSet(product) ? 'НАБОР' : product.crop === 'raspberry' ? 'САЖЕНЕЦ' : 'РАССАДА';
const shopSeedlingLabel = product => shopIsSet(product) ? 'Набор клубники' : product.crop === 'raspberry' ? 'Саженец малины' : 'Рассада клубники';
const shopVariety = product => varieties.find(variety => variety.slug === product.cultivarSlug);
const shopDisplayName = product => (product.name || shopVariety(product)?.name || product.expectedName).replace(/^Земляника садовая\s+/iu, 'Клубника ');
const shopHeadline = product => product.headline || shopDisplayName(product);
const shopLead = product => product.lead || buildShopLead(product);
const shopArticle = product => product.article || buildShopArticle(product);
function shopImage(product) {
  const feedItem = shopFeedItems.get(String(shopOfferFor(product)?.id || product.id));
  const yellow = product.crop === 'raspberry' && /ж[её]лт/iu.test(product.name || '');
  const black = product.crop === 'raspberry' && /бл[еэ]к\s*джевел|черн(?:ая|оплодн|оплодная)/iu.test(product.name || '');
  const fallback = black ? '/assets/raspberry-black-garden.webp' : yellow ? '/assets/raspberry-yellow-garden.webp' : `/assets/${product.crop}-garden.webp`;
  const local = feedItem?.imagePath || product.imagePath;
  if (/^\/assets\/shop\/\d+\.(?:jpg|png|webp)$/.test(local || '')) {
    return { src: local, alt: `Фото товара продавца: ${shopDisplayName(product)}`, caption: 'Фото товара из каталога продавца.' };
  }
  try {
    const remote = new URL(feedItem?.imageUrl || '');
    if (remote.protocol === 'https:' && remote.hostname === 'agrosemfond.ru') {
      return { src: fallback, remote: remote.href, remoteAlt: `Фото товара продавца: ${shopDisplayName(product)}`, alt: `Иллюстрация: ${shopCropLabel(product).toLowerCase()}`, caption: 'Иллюстрация культуры.' };
    }
  } catch {}
  const variety = shopVariety(product);
  if (variety) return cultivarImage(variety);
  return { src: fallback, alt: `Иллюстрация: ${shopCropLabel(product).toLowerCase()}`, caption: 'Иллюстрация культуры.' };
}

function shopCard(product) {
  const offer = shopOfferFor(product);
  const stock = shopStockFor(product);
  const image = shopImage(product);
  const name = shopDisplayName(product);
  const offerName = offer?.name.replace(/^Земляника садовая\s+/iu, 'Клубника ');
  const search = [...new Set([name, offerName, ...shopVariantsByCanonical.get(product.slug).flatMap(item => [item.name, item.id])].filter(Boolean))].join(' ').toLocaleLowerCase('ru').replaceAll('ё', 'е');
  return `<article class="shop-card" data-shop-card data-shop-canonical="${e(product.slug)}" data-crop="${e(product.crop)}" data-stock="${stock}" data-search="${e(search)}"><a class="shop-card-image" href="${shopProductPath(product)}" aria-label="Подробнее: ${e(name)}"><img src="${e(image.src)}" alt="${e(image.alt)}"${image.remote ? ` data-shop-remote="${e(image.remote)}" data-shop-remote-alt="${e(image.remoteAlt)}"` : ''} width="800" height="640" loading="lazy" decoding="async"></a><div class="shop-card-body"><span class="eyebrow">${e(shopCropLabel(product))} / ${shopPlantLabel(product)}</span><h3><a href="${shopProductPath(product)}">${e(name)}</a></h3>${offerName && offerName !== name ? `<small class="shop-sku">У продавца: ${e(offerName)}</small>` : ''}<p>${e(shopLead(product))}</p><div class="shop-card-bottom"><strong>${offer ? e(shopPrice(offer)) : shopStockLabel(stock)}</strong><a href="${shopProductPath(product)}">Подробнее ${arrow}</a></div></div></article>`;
}

function shopIndex() {
  const current = publicShopProducts.filter(shopOfferFor);
  const unavailable = publicShopProducts.filter(product => !shopOfferFor(product));
  const groups = [{ crop: 'raspberry', heading: 'Саженцы малины' }, { crop: 'strawberry', heading: 'Рассада клубники' }];
  const sections = groups.map(group => {
    const selected = [...current, ...unavailable].filter(product => product.crop === group.crop);
    return `<section class="section wrap shop-section" id="${group.crop === 'raspberry' ? 'malina' : 'klubnika'}" data-shop-section>${sectionHead('ВЫБРАТЬ И ПОСАДИТЬ', `${group.heading} · ${selected.length}`, 'Описание товара, посадка и наличие — на каждой странице.')}<div class="shop-grid">${selected.map(shopCard).join('')}</div></section>`;
  }).join('');
  const schema = siteUrl ? `<script type="application/ld+json">${JSON.stringify({ '@context': 'https://schema.org', '@graph': [
    { '@type': 'CollectionPage', name: 'Магазин саженцев малины и рассады клубники', url: `${siteUrl}/magazin/`, mainEntity: { '@type': 'ItemList', itemListElement: publicShopProducts.map((product, index) => ({ '@type': 'ListItem', position: index + 1, name: shopDisplayName(product), url: `${siteUrl}${shopProductPath(product)}` })) } },
    { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: 'Главная', item: `${siteUrl}/` }, { '@type': 'ListItem', position: 2, name: 'Магазин', item: `${siteUrl}/magazin/` }] }
  ] }).replaceAll('<', '\\u003c')}</script>` : '';
  return layout({ title: 'Магазин саженцев малины и клубники', description: 'Каталог саженцев малины и рассады клубники: фото, наличие, описание и посадка. Отдельная страница для каждого товара.', path: '/magazin/', active: 'shop', script: `${schema}<script defer src="/assets/shop-filter.js"></script>`, body: `<section class="simple-hero shop-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span>Магазин</div><span class="eyebrow">МАЛИНА — КЛУБНИКА / МАГАЗИН</span><h1>Саженцы малины<br><em>и рассада клубники.</em></h1><p>${publicShopProducts.length} товаров в каталоге. Откройте карточку, чтобы посмотреть описание, посадку и наличие.</p><div class="shop-hero-links"><a href="#malina">Малина ${arrow}</a><a href="#klubnika">Клубника ${arrow}</a></div></div></section><div class="wrap shop-filter" role="search"><label>Найти товар<input type="search" data-shop-query placeholder="Название или артикул" autocomplete="off"></label><label>Наличие<select data-shop-stock><option value="all">Все товары</option><option value="in_stock">Есть в наличии</option><option value="out_of_stock">Нет в наличии</option><option value="unknown">Наличие уточняется</option></select></label><p data-shop-count aria-live="polite">Показано ${publicShopProducts.length} товаров</p></div>${sections}<section class="inline-cta wrap"><div><span class="eyebrow light">ЕЩЁ НЕ ОПРЕДЕЛИЛИСЬ</span><h2>Сначала подберите сорт для своего города.</h2></div><a class="btn btn-cream" href="/podbor/">Открыть подбор ${arrow}</a></section>` });
}

function shopLanding(product) {
  const variety = shopVariety(product);
  const catalog = product.cultivarSlug ? publicCultivars.get(product.cultivarSlug) : null;
  const offer = shopOfferFor(product);
  const stock = shopStockFor(product);
  const image = shopImage(product);
  const name = shopDisplayName(product);
  const offerName = offer?.name.replace(/^Земляника садовая\s+/iu, 'Клубника ');
  const article = shopArticle(product);
  const lead = shopLead(product);
  const path = shopProductPath(product);
  const title = `${name}: описание и посадка`;
  const description = product.lead
    ? `${name}. ${offer ? 'Есть в наличии.' : `${shopStockLabel(stock)}.`} ${lead}`
    : `${name}: описание товара, посадка и подбор по городу. ${offer ? `Цена ${shopPrice(offer)}.` : `${shopStockLabel(stock)}.`}`;
  const productImage = /^https:\/\//i.test(image.src) ? image.src : `${siteUrl}${siteBase}${image.src}`;
  const regionNumbers = [...new Set((catalog?.admissions || []).map(admission => admission.admission_region_number))].sort((a, b) => a - b);
  const regionNames = regionNumbers.map(number => publicCatalog.regions.find(region => region.admission_region_number === number)?.admission_region_name).filter(Boolean);
  const regionText = regionNumbers.length === 12 ? 'во всех 12 регионах допуска' : `в регионах: ${regionNames.join(', ')}`;
  const regionSource = catalog?.admissions?.[0]?.source_url;
  const regionBody = regionNumbers.length
    ? `<p>По Госреестру РФ 2024 года сорт допущен ${e(regionText)}.</p>${regionSource ? `<p><a class="text-link" href="${e(regionSource)}" target="_blank" rel="noopener noreferrer">Запись Госреестра ↗</a></p>` : ''}`
    : '';
  const order = offer
    ? `<div class="shop-order"><span class="eyebrow">ПРЕДЛОЖЕНИЕ ПРОДАВЦА</span><h2>${e(offerName)}</h2><p class="shop-sku">Артикул ${e(offer.id)}</p><p class="shop-order-price">${e(shopPrice(offer))}</p><p>Продавец: Агросемфонд · обновлено ${e(shopSnapshot.checkedAt.slice(0, 10).split('-').reverse().join('.'))}</p><a class="btn btn-dark" href="${e(offer.affiliateUrl)}" target="_blank" rel="sponsored nofollow noopener noreferrer" data-affiliate-offer="${e(offer.id)}"${product.cultivarSlug ? ` data-cultivar="${e(product.cultivarSlug)}"` : ''}>Заказать у продавца ${arrow}</a><small>Партнёрская ссылка · заказ на сайте продавца.</small></div>`
    : `<div class="shop-order shop-order-empty"><span class="eyebrow">ПРЕДЛОЖЕНИЕ ПРОДАВЦА</span><h2>${shopStockLabel(stock)}</h2></div>`;
  const varietyFacts = variety
    ? [['Культура', shopCropLabel(product)], ['Плодоношение', variety.fruitingLabel === shopCropLabel(product) ? '' : variety.fruitingLabel], ['Срок', variety.period], ['Место', variety.place]]
      .filter(([, value]) => value && value !== '—')
      .map(([label, value]) => `<div><dt>${label}</dt><dd>${e(value)}</dd></div>`).join('')
    : '';
  const varietyBody = variety
    ? `<section><span class="eyebrow">01 / СОРТ</span><h2>О сорте «${e(variety.name)}»</h2><p>${e(variety.note)}</p><dl class="shop-facts">${varietyFacts}</dl><p><a class="text-link" href="/sorta/${e(product.cultivarSlug)}/">Полная карточка сорта и отзывы ↗</a></p></section>`
    : `<section><span class="eyebrow">01 / ТОВАР</span><h2>О товаре</h2><dl class="shop-facts"><div><dt>Культура</dt><dd>${e(shopCropLabel(product))}</dd></div><div><dt>Раздел продавца</dt><dd>${e(product.categoryId)}</dd></div></dl></section>`;
  const editorial = `<section class="shop-editorial"><span class="eyebrow">ПОДРОБНЕЕ О ПОЗИЦИИ</span><h2>${e(article.title)}</h2>${article.paragraphs.map(paragraph => `<p>${e(paragraph)}</p>`).join('')}</section>`;
  const planting = `<section id="posadka"><span class="eyebrow">03 / ПОСАДКА</span><h2>${e(product.planting.title)}</h2><ol class="shop-steps">${product.planting.steps.map(step => `<li>${e(step)}</li>`).join('')}</ol><p><a class="text-link" href="${e(product.planting.guideHref)}">Подробная инструкция по посадке ↗</a></p></section>`;
  const checklist = `<section><span class="eyebrow">04 / ПЕРЕД ЗАКАЗОМ</span><h2>Проверьте товар</h2><ul class="shop-checklist">${product.buyerChecklist.map(item => `<li>${e(item)}</li>`).join('')}</ul></section>`;
  const sourceList = [
    ...(product.merchantUrl ? [{ label: 'Описание товара у продавца', url: product.merchantUrl }] : []),
    ...product.sources
  ];
  const sources = `<section class="shop-sources"><span class="eyebrow">ИСТОЧНИКИ</span><h2>Источники</h2><ul>${sourceList.map(source => `<li><a href="${e(source.url)}" target="_blank" rel="noopener noreferrer">${e(source.label)} ↗</a></li>`).join('')}</ul></section>`;
  const related = relatedShopProducts(product, publicShopProducts, shopOfferFor);
  const aside = `<aside class="shop-product-aside"><span class="eyebrow">ДАЛЬШЕ</span><h2>Подберите под свой сад</h2>${variety ? `<a href="/sorta/${e(product.cultivarSlug)}/">Описание и отзывы ${arrow}</a>` : ''}<a href="/podbor/">Подбор по городу ${arrow}</a><a href="${e(product.planting.guideHref)}">Посадка и уход ${arrow}</a></aside>`;
  const schema = siteUrl ? `<script type="application/ld+json">${JSON.stringify({ '@context': 'https://schema.org', '@graph': [
    offer ? { '@type': 'Product', name, description, image: productImage, url: `${siteUrl}${path}`, sku: String(offer.id), offers: { '@type': 'Offer', url: offer.merchantUrl, price: (offer.priceMinor / 100).toFixed(2), priceCurrency: 'RUB', availability: 'https://schema.org/InStock', seller: { '@type': 'Organization', name: 'Агросемфонд' } } }
      : { '@type': 'WebPage', name: title, description, url: `${siteUrl}${path}` },
    { '@type': 'BreadcrumbList', itemListElement: [{ '@type': 'ListItem', position: 1, name: 'Главная', item: `${siteUrl}/` }, { '@type': 'ListItem', position: 2, name: 'Магазин', item: `${siteUrl}/magazin/` }, { '@type': 'ListItem', position: 3, name, item: `${siteUrl}${path}` }] }
  ] }).replaceAll('<', '\\u003c')}</script>` : '';
  const body = `<article class="shop-product"><header class="shop-product-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span><a href="/magazin/">Магазин</a><span> / </span>${e(name)}</div><span class="eyebrow">${e(shopCropLabel(product))} / ${shopPlantLabel(product)}</span><h1>${e(shopHeadline(product))}</h1>${product.lead ? `<p class="shop-product-lead">${e(lead)}</p>` : ''}<div class="shop-product-main"><figure class="shop-product-image"><img src="${e(image.src)}"${image.remote ? ` data-shop-remote="${e(image.remote)}" data-shop-remote-alt="${e(image.remoteAlt)}"` : ''} alt="${e(image.alt)}" width="900" height="720"><figcaption>${e(image.caption)}</figcaption></figure>${order}</div></div></header><div class="wrap shop-product-content"><div class="shop-product-article">${varietyBody}${editorial}<section id="regiony"><span class="eyebrow">02 / РЕГИОНЫ</span><h2>Где выращивать</h2>${regionBody}<p><a class="btn btn-outline" href="/podbor/">Проверить свой город ${arrow}</a></p></section>${planting}${checklist}${sources}</div>${aside}</div></article><section class="section wrap shop-related">${sectionHead('ЕЩЁ ПО ТЕМЕ', 'Похожие саженцы', '', '<a class="text-link" href="/magazin/">Весь магазин ↗</a>')}<div class="shop-grid">${related.map(shopCard).join('')}</div></section>`;
  const socialImage = variety ? cultivarImage(variety).src : product.crop === 'raspberry' ? '/assets/raspberry-garden.webp' : '/assets/strawberry-garden.webp';
  const socialImageAlt = variety ? cultivarImage(variety).alt : `Иллюстрация: ${shopCropLabel(product).toLowerCase()}`;
  return layout({ title, description, path, active: 'shop', socialImage, socialImageAlt, script: `${schema}<script defer src="/assets/shop-filter.js"></script>`, body });
}

function shopVariantRedirect(product) {
  const primary = publicShopBySlug.get(product.canonicalSlug);
  if (!primary) throw new Error(`Missing primary shop product for ${product.slug}`);
  const target = `${siteBase}${shopProductPath(primary)}`;
  const canonical = siteUrl ? `<link rel="canonical" href="${e(siteUrl + shopProductPath(primary))}">` : '';
  return `<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="robots" content="noindex,follow">${canonical}<meta http-equiv="refresh" content="0;url=${e(target)}"><title>${e(shopDisplayName(primary))} — магазин</title></head><body><p>Товар доступен на <a href="${e(target)}">общей странице «${e(shopDisplayName(primary))}»</a>.</p></body></html>`;
}

function withShopLink(html, variety) {
  const product = publicShopProducts.find(item => item.cultivarSlug === variety.slug);
  if (!product) return html;
  const offer = shopOfferFor(product);
  const stock = shopStockFor(product);
  const availability = offer ? `Есть в наличии · ${e(shopPrice(offer))}` : shopStockLabel(stock);
  const section = `<section class="section wrap shop-variety-link"><div><span class="eyebrow">${shopPlantLabel(product)} СОРТА</span><h2>${e(variety.name)}: предложение и посадка</h2><p>На странице товара собраны описание, регионы допуска и шаги посадки.</p><p class="shop-variety-availability">${availability}</p></div><a class="btn btn-dark" href="${shopProductPath(product)}">Посмотреть товар ${arrow}</a></section>`;
  return html.replace('</main>', `${section}</main>`);
}

function withEvidence(html, variety) {
  const row = publicCultivars.get(variety.slug);
  const section = evidenceSection(row) + admissionSection(row, { cities, regions: publicCatalog.regions });
  if (variety.slug === 'festivalnaya') {
    html = html.replace(
      'Откройте исходное описание и проверьте условия испытания сорта.',
      'Запись Госреестра подтверждает название и регионы допуска в издании 2024 года. '
    );
  }
  return section ? html.replace('<section class="section wrap source-panel">', `${section}<section class="section wrap source-panel">`) : html;
}

function withRelatedReading(html, variety) {
  const score = candidate =>
    Number(variety.fruiting !== 'unknown' && candidate.fruiting === variety.fruiting) * 2
    + Number(variety.fruitColor && variety.fruitColor !== 'unknown' && candidate.fruitColor === variety.fruitColor) * 2
    + Number(variety.harvestTiming !== 'unknown' && candidate.harvestTiming === variety.harvestTiming);
  const similar = varieties.filter(candidate => candidate.slug !== variety.slug && candidate.cropKey === variety.cropKey)
    .sort((left, right) => score(right) - score(left) || left.name.localeCompare(right.name, 'ru'))
    .slice(0, 3);
  const reading = articles.filter(article => article.relatedVarieties?.includes(variety.slug)).slice(0, 3);
  const varietyLinks = similar.map(candidate => {
    const image = cultivarImage(candidate);
    return `<a class="variety-related-card" href="/sorta/${e(candidate.slug)}/"><img src="${image.src}" alt="${e(image.alt)}" width="${image.width}" height="${image.height}" loading="lazy" decoding="async"><span>${e(candidate.crop)}</span><strong>${e(candidate.name)}</strong></a>`;
  }).join('');
  const readingLinks = reading.length
    ? `<div class="variety-related-reading"><h3>Читайте по теме</h3><ul>${reading.map(article => `<li><a href="${articlePath(article)}">${e(article.title)} ${arrow}</a></li>`).join('')}</ul></div>`
    : '';
  const section = `<section class="section wrap variety-related" aria-labelledby="variety-related-title"><div class="section-head"><div><span class="eyebrow">ПРОДОЛЖИТЬ ВЫБОР</span><h2 id="variety-related-title">Другие сорта для сравнения</h2><p>Откройте карточки ${variety.cropKey === 'raspberry' ? 'малины' : 'клубники'} и сравните признаки по источникам.</p></div><a class="text-link" href="/sorta/">Весь каталог ↗</a></div><div class="variety-related-grid">${varietyLinks}</div>${readingLinks}</section>`;
  return html.replace('<section class="section wrap"><div class="next-row">', `${section}<section class="section wrap"><div class="next-row">`);
}

function withCultivarReviews(html, variety) {
  return html.replace('</head>', '<script defer src="/assets/reviews.js"></script></head>').replace('</main>', `${cultivarReviews(variety)}</main>`);
}

const lotChecklist = layout({ title: 'Проверить документы на партию саженцев', description: 'Практический список документов для проверки происхождения и состояния партии малины или клубники перед покупкой.', path: '/proverka-partii/', active: 'guide', script: '<script defer src="/assets/lot-checklist.js"></script>', body: `<section class="simple-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span><a href="/in-vitro/">Посадочный материал</a><span> / </span>Проверка партии</div><span class="eyebrow">ИНСТРУМЕНТ / ПОСАДОЧНЫЙ МАТЕРИАЛ</span><h1>Проверьте<br><em>партию.</em></h1><p>Соберите документы на конкретную партию, проверьте происхождение саженцев и условия хранения.</p></div></section><section class="section wrap" id="lot-checklist"><div class="lot-checklist-panel"><label class="lot-kind-label" for="planting-stock">Тип посадочного материала</label><select id="planting-stock" name="planting-stock"><option value="frigo">Клубника Frigo</option><option value="tissue">Микрорастения после In Vitro</option><option value="other">Другой тип растений</option></select><h2>Документы и сведения о партии</h2><p>Попросите связать каждый документ с названием сорта и конкретной партией, которую вам отправят.</p><fieldset class="lot-checks"><legend>Для любой партии</legend><label><input type="checkbox"><span>Название сорта, поставщик, номер партии и дата отгрузки указаны вместе.</span></label><label><input type="checkbox"><span>Указаны тип растения, способ размножения и стадия доращивания.</span></label><label><input type="checkbox"><span>Есть документы о происхождении маточного материала и сортовой идентичности.</span></label><label><input type="checkbox"><span>Фитосанитарный документ называет проверенные организмы, метод, лабораторию, дату, образец и связь образца с партией.</span></label><label><input type="checkbox"><span>Есть письменные требования поставщика к перевозке, хранению и сроку посадки.</span></label></fieldset><fieldset class="lot-checks" data-stock-kind="frigo"><legend>Дополнительно для Frigo</legend><label><input type="checkbox"><span>Поставщик объяснил, что означает заявленный класс и по какому стандарту он определён.</span></label><label><input type="checkbox"><span>Если для заявленного срока урожая важна индукция цветочной почки, поставщик указал её статус и основание.</span></label><label><input type="checkbox"><span>Есть прослеживаемые сведения о температуре хранения и перевозки до передачи партии.</span></label></fieldset><fieldset class="lot-checks" data-stock-kind="tissue" hidden><legend>Дополнительно для растений после In Vitro</legend><label><input type="checkbox"><span>Указаны лаборатория, дата выхода из стерильной культуры и этап адаптации Ex Vitro.</span></label><label><input type="checkbox"><span>Результаты фитосанитарных тестов относятся к исходной партии/маточнику и перечисляют конкретные тесты.</span></label><label><input type="checkbox"><span>Поставщик дал условия адаптации, упаковки и перехода к открытому воздуху.</span></label></fieldset><fieldset class="lot-checks" data-stock-kind="other" hidden><legend>Уточните для выбранного формата</legend><label><input type="checkbox"><span>Получена спецификация именно этого формата растения и требований к его посадке.</span></label><label><input type="checkbox"><span>Состояние корней и надземной части описано для партии до отгрузки.</span></label><label><input type="checkbox"><span>Поставщик письменно обозначил допустимый срок и режим хранения.</span></label></fieldset><p id="checklist-status" class="lot-checklist-status" role="status" aria-live="polite"></p><details class="lot-request"><summary>Составить запрос продавцу по недостающим пунктам</summary><p>Отметьте уже полученные сведения. Текст ниже останется только в вашем браузере; перед отправкой проверьте его и удалите лишнее.</p><label for="lot-request-text">Текст запроса</label><textarea id="lot-request-text" rows="12" readonly></textarea><button class="btn btn-outline" id="lot-copy" type="button">Скопировать вопросы</button><p id="lot-copy-status" role="status" aria-live="polite"></p></details><p class="lot-checklist-limit">В результатах тестирования сопоставьте патоген, образец, метод, дату и номер партии.</p><a class="btn btn-outline" href="/in-vitro/">Как читать сведения об In Vitro ${arrow}</a></div><aside class="lot-checklist-sources"><span class="eyebrow">ОСНОВАНИЯ</span><h2>Проверяйте связь документа с растением</h2><p>Культура тканей описывает способ размножения. Диагностика и сортовая идентичность требуют отдельных методов и записей.</p><a href="https://fps.ucdavis.edu/strawberry.cfm" target="_blank" rel="noopener noreferrer">UC Davis Foundation Plant Services · клубника ↗</a><a href="https://californiaagriculture.org/api/v1/articles/112420-meristem-culture-for-elimination-of-strawberry-viruses.pdf" target="_blank" rel="noopener noreferrer">California Agriculture · сочетание меристемы и термообработки ↗</a></aside></section>` });

const plantingCalculator = layout({
  title: 'Калькулятор саженцев малины и клубники — сколько нужно для грядки',
  description: 'Рассчитайте количество саженцев по размерам грядки, числу рядов и выбранным расстояниям. Формула и допущения открыты; схема посадки задаётся вами.',
  path: '/instrumenty/raschet-sazhencev/',
  script: '<script type="module" src="/assets/planting.js"></script>',
  body: `<section class="simple-hero planting-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span>Расчёт саженцев</div><span class="eyebrow">СХЕМА ПОСАДКИ / ГЕОМЕТРИЯ</span><h1>Сколько саженцев<br><em>поместится?</em></h1><p>Укажите размеры грядки и шаг посадки, чтобы рассчитать количество саженцев.</p></div></section>
  <section class="section wrap planting-layout"><div class="planting-form-panel"><span class="eyebrow">01 / ВАШИ РАЗМЕРЫ</span><h2>План грядки</h2><form id="planting-form"><div class="planting-fields"><label>Длина одной грядки, м<input name="length" type="number" inputmode="decimal" min="0.01" max="10000" step="any" placeholder="Например, 10" required></label><label>Ширина одной грядки, м<input name="width" type="number" inputmode="decimal" min="0.01" max="1000" step="any" placeholder="Например, 1" required></label><label>Число одинаковых грядок<input name="beds" type="number" inputmode="numeric" min="1" max="10000" step="1" value="1" required></label><label>Между рядами, см<input name="rowSpacing" type="number" inputmode="decimal" min="0.01" max="100000" step="any" placeholder="Укажите ваш шаг" required></label><label>Между растениями в ряду, см<input name="plantSpacing" type="number" inputmode="decimal" min="0.01" max="100000" step="any" placeholder="Укажите ваш шаг" required></label></div><button class="btn btn-dark" type="submit">Посчитать ${arrow}</button></form><div id="planting-result" class="planting-result" role="status" aria-live="polite" tabindex="-1" hidden></div></div><aside class="planting-method"><span class="eyebrow">02 / КАК СЧИТАЕМ</span><h2>Прозрачная формула</h2><p>Для прямых параллельных рядов: число рядов = целая часть от ширины грядки ÷ междурядье. Растений в ряду = целая часть от длины грядки ÷ шага между растениями. Итог — произведение этих чисел на количество грядок.</p><p>Первое растение и первый ряд расположены на расстоянии половины шага от края. Для проходов, шахматной схемы и запаса саженцев сделайте отдельную поправку.</p><p>Шаг посадки выбирайте по культуре, сорту и способу выращивания.</p><a class="text-link" href="/podbor/">После расчёта — выбрать сорт ↗</a></aside></section>`
});

const trellisCalculator = layout({
  title: 'Калькулятор шпалеры для малины — опоры, проволока и смета',
  description: 'Рассчитайте опоры и проволоку для прямых рядов малины. Введите свои цены и получите смету материалов с открытой формулой.',
  path: '/instrumenty/raschet-shpalery/',
  script: '<script type="module" src="/assets/trellis.js"></script>',
  body: `<section class="simple-hero planting-hero"><div class="wrap"><div class="breadcrumbs"><a href="/">Главная</a><span> / </span><a href="/instrumenty/">Инструменты</a><span> / </span>Расчёт шпалеры</div><span class="eyebrow">МАЛИНА / ПЛАНИРОВАНИЕ</span><h1>Сколько нужно<br><em>опор и проволоки?</em></h1><p>Задайте схему прямых рядов и, если знаете цены, посчитайте стоимость опор и проволоки без чужих прайсов.</p></div></section>
  <section class="section wrap planting-layout"><div class="planting-form-panel"><span class="eyebrow">01 / ВАША СХЕМА</span><h2>Размеры шпалеры</h2><form id="trellis-form"><div class="planting-fields"><label>Длина одного ряда, м<input name="length" type="number" inputmode="decimal" min="0.01" max="10000" step="any" placeholder="Например, 25" required></label><label>Число одинаковых рядов<input name="rows" type="number" inputmode="numeric" min="1" max="1000" step="1" value="1" required></label><label>Максимальный пролёт между опорами, м<input name="maxSpan" type="number" inputmode="decimal" min="0.01" max="1000" step="any" placeholder="Укажите свой предел" required></label><label>Продольных линий проволоки на ряд<input name="wireLines" type="number" inputmode="numeric" min="1" max="20" step="1" value="2" required></label></div><fieldset class="trellis-prices"><legend>Цены для сметы — по желанию</legend><p>Введите все три цены из своего предложения. Если оставить поля пустыми, покажем только количество материалов.</p><div class="planting-fields"><label>Концевая опора, ₽/шт<input name="endPostPrice" type="number" inputmode="decimal" min="0" max="1000000" step="0.01" placeholder="Ваша цена"></label><label>Промежуточная опора, ₽/шт<input name="intermediatePostPrice" type="number" inputmode="decimal" min="0" max="1000000" step="0.01" placeholder="Ваша цена"></label><label>Проволока, ₽/м<input name="wirePrice" type="number" inputmode="decimal" min="0" max="1000000" step="0.01" placeholder="Ваша цена"></label></div></fieldset><button class="btn btn-dark" type="submit">Рассчитать материалы ${arrow}</button></form><div id="trellis-result" class="planting-result" role="status" aria-live="polite" tabindex="-1" hidden></div></div><aside class="planting-method"><span class="eyebrow">02 / ФОРМУЛА И ГРАНИЦЫ</span><h2>Как считаем</h2><p>Пролётов в одном ряду = округлённая вверх длина ряда ÷ заданный вами максимальный пролёт. Опор в ряду = пролётов + 1: две концевые и остальные промежуточные. Проволока = длина ряда × число рядов × число продольных линий.</p><p>Смета = концевые опоры × их цена + промежуточные опоры × их цена + метры проволоки × цена за метр. В расчёте только опоры и прямые линии проволоки; анкеры, крепёж, доставка и работа потребуют отдельных строк бюджета. Шаг опор и прочность конструкции проверьте для своего участка.</p><a class="text-link" href="/zhurnal/shpalera-dlya-maliny-kak-vybrat-oporu/">Как устроена шпалера для малины ↗</a><a class="text-link" href="/instrumenty/raschet-sazhencev/">Рассчитать посадку ↗</a></aside></section>`
});

